 private final Map<String,LinkedHashSet<String>> companyCodes=new HashMap<>();private final Map<String,String> companyCanonical=new HashMap<>();
 private void rebuildCompanyCodes(){if(indexedCatalog==docs){rebuildFollowed();return;}indexedCatalog=docs;companyCodes.clear();companyCanonical.clear();for(int i=0;i<docs.length();i++){JSONArray refs=docs.optJSONObject(i).optJSONArray("company_securities");if(refs==null)continue;for(int n=0;n<refs.length();n++){JSONObject r=refs.optJSONObject(n);if(r==null)continue;String code=r.optString("code"),exchange=r.optString("exchange");if(!code.matches("[0-9]{5,6}|[A-Z]{1,5}(?:[.][A-Z])?")||!exchange.matches("sh|sz|bj|hk|us"))continue;String name=r.optString("name"),canonical=r.optString("canonical_name",name);companyCanonical.put(name,canonical);companyCodes.computeIfAbsent(name,k->new LinkedHashSet<>()).add(code+"."+exchange.toUpperCase(Locale.ROOT));companyCodes.computeIfAbsent(canonical,k->new LinkedHashSet<>()).add(code+"."+exchange.toUpperCase(Locale.ROOT));}}companySearchText.clear();for(Map.Entry<String,String> alias:companyCanonical.entrySet())companySearchText.merge(alias.getValue()," "+alias.getKey().toLowerCase(Locale.ROOT),String::concat);rebuildFollowed();}
 private void rebuildFollowed(){followedCompanies.clear();for(Map.Entry<String,?> e:prefs.getAll().entrySet())if(e.getKey().startsWith("follow:")&&Boolean.TRUE.equals(e.getValue())){String name=e.getKey().substring(7);followedCompanies.add(companyCanonical.getOrDefault(name,name));}}
 private boolean companyMember(JSONObject d,String name){JSONArray values=d.optJSONArray("companies");if(values==null)return false;for(int i=0;i<values.length();i++){String raw=values.optString(i);if(name.equals(raw)||name.equals(companyCanonical.get(raw)))return true;}return false;}
 private boolean companyIsFollowed(String name){return followedCompanies.contains(companyCanonical.getOrDefault(name,name));}
 private void toggleCompanyFollow(){boolean value=!companyIsFollowed(company);android.content.SharedPreferences.Editor edit=prefs.edit().putBoolean("follow:"+company,value);for(Map.Entry<String,String> alias:companyCanonical.entrySet())if(alias.getValue().equals(company))edit.putBoolean("follow:"+alias.getKey(),value);edit.apply();render();}
 private boolean companyQuery(String name){String q=query.trim().toLowerCase(Locale.ROOT);if(LibraryViews.isCodeQuery(query.trim())){Set<String> codes=companyCodes.get(name);if(codes==null)return false;for(String code:codes)if(code.toLowerCase(Locale.ROOT).equals(q)||code.substring(0,code.lastIndexOf('.')).equalsIgnoreCase(q))return true;return false;}if(companySearchText.getOrDefault(name,"").contains(q))return true;return companyLabel(name).toLowerCase(Locale.ROOT).contains(q);}
 private String companyLabel(String name){Set<String> codes=companyCodes.get(name);return name+" · "+(codes==null||codes.isEmpty()?"代码待匹配":android.text.TextUtils.join(" / ",codes));}
 private String date(String value){return LibraryViews.date(value);}
 private boolean followed(JSONObject d){JSONArray names=d.optJSONArray("companies");if(names!=null)for(int i=0;i<names.length();i++)if(companyIsFollowed(companyCanonical.getOrDefault(names.optString(i),names.optString(i))))return true;return false;}
 private float progress(JSONObject d){return prefs.getFloat(LibraryViews.progressKey(d),0);}
 private boolean visible(JSONObject d){return LibraryViews.matches(d,query,sourceFilter,dateDays,feedMode,prefs.getBoolean("read:"+d.optString("document_id"),false),followed(d),progress(d),java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai")));}
 private void filterDialog(){String[] options={"全部时间","今天","近 7 天","近 30 天","按来源筛选","清除所有筛选"};new AlertDialog.Builder(this).setTitle("资料筛选").setItems(options,(dialog,which)->{if(which<4){dateDays=new int[]{0,1,7,30}[which];listLimit=60;render();}else if(which==4){TreeSet<String> sources=new TreeSet<>();for(int i=0;i<docs.length();i++)if(!docs.optJSONObject(i).optString("source_name").isEmpty())sources.add(docs.optJSONObject(i).optString("source_name"));ArrayList<String> choices=new ArrayList<>();choices.add("全部来源");choices.addAll(sources);new AlertDialog.Builder(this).setTitle("资料来源").setItems(choices.toArray(new String[0]),(d,n)->{sourceFilter=n==0?"":choices.get(n);listLimit=60;render();}).show();}else{dateDays=0;sourceFilter="";feedMode="全部";query="";search.setText("");render();}}).show();}
