 private void dashboard(){java.time.LocalDate today=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai"));int added=0,watchUnread=0,resuming=0;for(int i=0;i<docs.length();i++){JSONObject d=docs.optJSONObject(i);if(ResearchHome.importedToday(d,today))added++;if(followed(d)&&!prefs.getBoolean("read:"+d.optString("document_id"),false))watchUnread++;float p=progress(d);if(p>.02f&&p<.98f)resuming++;}LinearLayout panel=new LinearLayout(this);String[] titles={"今日收录 "+added,"关注未读 "+watchUnread,"继续阅读 "+resuming};for(int n=0;n<titles.length;n++){final int which=n;Button b=button(titles[n],()->{if(which==1&&followedCompanies.isEmpty()){tab="公司";company="";render();}else selectFeed(which==0?"今日收录":which==1?"关注":"续读");});b.setTag("home:metric:"+n);b.setPadding(dp(4),dp(4),dp(4),dp(4));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(44),1);lp.setMargins(dp(2),dp(3),dp(2),dp(5));panel.addView(b,lp);}content.addView(panel);LinearLayout modes=new LinearLayout(this);String[] names={"最新","今日","关注","续读","未读"},values={"全部","今日收录","关注","续读","未读"};for(int n=0;n<names.length;n++){String value=values[n];Button b=button(names[n],()->selectFeed(value));b.setPadding(dp(4),dp(4),dp(4),dp(4));b.setBackground(surface(feedMode.equals(value)?GREEN:Color.WHITE,10));b.setTextColor(feedMode.equals(value)?Color.WHITE:GREEN);modes.addView(b,new LinearLayout.LayoutParams(0,dp(40),1));}content.addView(modes);if(!feedMode.equals("全部")||!query.isEmpty()||dateDays!=0||!sourceFilter.isEmpty())return;
  String last=prefs.getString("last_article","");for(int i=0;i<docs.length();i++){JSONObject d=docs.optJSONObject(i);if(d.optString("document_id").equals(last)&&progress(d)>.02f&&progress(d)<.98f){Button resume=button("继续上次 · "+ResearchHome.displayTitle(d),()->open(d));resume.setMaxLines(2);resume.setEllipsize(TextUtils.TruncateAt.END);content.addView(resume);break;}}
  int shown=0;for(int i=0;i<docs.length()&&shown<2;i++){JSONObject d=docs.optJSONObject(i);if(!followed(d)||prefs.getBoolean("read:"+d.optString("document_id"),false))continue;if(shown==0)content.addView(bold("关注公司 · 研究更新",15));LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(8),dp(12),dp(8));card.setBackground(surface(Color.rgb(232,241,235),12));TextView title=bold(ResearchHome.displayTitle(d),15);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);card.addView(title);TextView badge=text(date(d.optString("published_at"))+" · "+d.optString("source_name")+"  ·  未读",10);badge.setTag("read:"+d.optString("document_id"));card.addView(badge);card.setOnClickListener(v->open(d));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,dp(4));content.addView(card,lp);homeFeatured.add(d.optString("document_id"));shown++;}if(shown>0)content.addView(bold("全部研究",15));
 }
 private void refreshHomeCounts(){if(content.findViewWithTag("home:metric:0")==null)return;int added=0,watch=0,resuming=0;java.time.LocalDate today=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Shanghai"));for(int n=0;n<docs.length();n++){JSONObject d=docs.optJSONObject(n);if(ResearchHome.importedToday(d,today))added++;if(followed(d)&&!prefs.getBoolean("read:"+d.optString("document_id"),false))watch++;float p=progress(d);if(p>.02f&&p<.98f)resuming++;}String[] values={"今日收录 "+added,"关注未读 "+watch,"继续阅读 "+resuming};for(int n=0;n<values.length;n++){View v=content.findViewWithTag("home:metric:"+n);if(v instanceof Button)((Button)v).setText(values[n]);}}
 private void savePosition(){if(!reading||currentArticle==null||scroll==null||articleRenderPending)return;int range=Math.max(0,content.getHeight()-scroll.getHeight());float value=range==0?0:Math.max(0,Math.min(1f,(float)scroll.getScrollY()/range));prefs.edit().putFloat(LibraryViews.progressKey(currentArticle),value).putString("last_article",currentArticle.optString("document_id")).apply();}
 private LinearLayout attachmentBoxForArticle;
 private void tableOfContents(){if(articleRenderPending){Toast.makeText(this,"正在排版章节，请稍候",Toast.LENGTH_SHORT).show();return;}ArrayList<View> entries=new ArrayList<>();ArrayList<String> titles=new ArrayList<>();for(TextView heading:headings)if(heading.isAttachedToWindow()){entries.add(heading);titles.add(heading.getText().toString());}if(attachmentBoxForArticle!=null&&attachmentBoxForArticle.isAttachedToWindow()&&attachmentBoxForArticle.getChildCount()>0){entries.add(attachmentBoxForArticle);titles.add("原件与附件");}if(entries.isEmpty()){Toast.makeText(this,"原文没有可识别的章节标题或附件",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("章节与附件").setItems(titles.toArray(new String[0]),(dialog,index)->{View view=entries.get(index);android.graphics.Rect rect=new android.graphics.Rect();view.getDrawingRect(rect);content.offsetDescendantRectToMyCoords(view,rect);scroll.smoothScrollTo(0,Math.max(0,rect.top-dp(12)));}).show();}
 private void beginReader(){foreground.removeCallbacks(searchRefresh);((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);search.clearFocus();root.requestFocus();if(!reading){returnList=content;returnListY=scroll.getScrollY();scroll.removeAllViews();content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);scroll.addView(content);}navigationGeneration++;}
 private void returnToList(){savePosition();pendingImages.clear();articleRenderPending=false;if(returnList==null){render();return;}LinearLayout previous=returnList;int y=returnListY;returnList=null;currentArticle=null;readerMode(false);updateSyncStatus();scroll.removeAllViews();content=previous;scroll.addView(content);refreshHomeCounts();final int generation=++navigationGeneration;
  // Keep the exact list snapshot, including loaded pages and unread-filter membership.
  for(int i=0;i<content.getChildCount();i++){View child=content.getChildAt(i);if(child instanceof LinearLayout)for(int n=0;n<((LinearLayout)child).getChildCount();n++){View item=((LinearLayout)child).getChildAt(n);if(item instanceof TextView&&item.getTag() instanceof String){String id=(String)item.getTag();if(id.startsWith("read:")){TextView badge=(TextView)item;String value=badge.getText().toString();if(prefs.getBoolean(id,false))value=value.replace("  ·  未读","  ·  已读");value=value.replace("  ★","");badge.setText(value+(prefs.getBoolean("star:"+id.substring(5),false)?"  ★":""));}}}}
  scroll.post(()->{if(!reading&&navigationGeneration==generation)scroll.scrollTo(0,y);});
 }
