  scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setOnTouchListener((v,e)->{if(articleRenderPending&&e.getActionMasked()==MotionEvent.ACTION_MOVE)userMovedDuringRender=true;return false;});scroll.setOnScrollChangeListener((View v,int x,int y,int oldX,int oldY)->{scheduleImages();if(reading&&currentArticle!=null&&readingProgress!=null){int range=content.getHeight()-scroll.getHeight();int percent=range>0?Math.min(100,Math.round(100f*y/range)):0;if(percent!=lastReadPercent){lastReadPercent=percent;readingProgress.setText(articleRenderPending?"正文排版中…":"阅读进度 "+percent+"% · 自动保存位置");}}});content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
