 private String originalType="",originalState="";
 private void originalFilters(String[] titles,String[] values,boolean types){HorizontalScrollView strip=new HorizontalScrollView(this);strip.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);strip.addView(row);for(int n=0;n<titles.length;n++){String value=values[n];boolean active=(types?originalType:originalState).equals(value);Button b=button(titles[n],()->{if(types)originalType=value;else originalState=value;listLimit=60;render();});b.setTextColor(active?Color.WHITE:GREEN);b.setBackground(surface(active?GREEN:Color.WHITE,10));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(42));lp.setMargins(0,dp(4),dp(6),dp(4));row.addView(b,lp);}content.addView(strip);}
 private void renderOriginals(){originalFilters(new String[]{"全部文件","PDF","音频","表格","图片"},new String[]{"","pdf","audio","file","image"},true);originalFilters(new String[]{"全部状态","本机可用","云端就绪","待获取","获取失败"},new String[]{"","local","ready","missing","failed"},false);ArrayList<JSONObject> documents=new ArrayList<>();ArrayList<OriginalFiles.Entry> entries=new ArrayList<>();int local=0,ready=0;for(int i=0;i<docs.length();i++){JSONObject d=docs.optJSONObject(i);if(!industry.equals("全部")&&!contains(d.optJSONArray("industries"),industry))continue;if(!company.isEmpty()&&!companyMember(d,company))continue;if(!visible(d))continue;for(OriginalFiles.Entry e:OriginalFiles.entries(d)){boolean cached=originalCached(e.item);if(!OriginalFiles.matches(d,e.item,query,originalType,originalState,cached))continue;documents.add(d);entries.add(e);if(cached)local++;if(e.item.optString("status").equals("ready"))ready++;}}content.addView(text("匹配 "+entries.size()+" 项 · 云端就绪 "+ready+" · 本机可用 "+local,12));for(int i=0;i<Math.min(listLimit,entries.size());i++){JSONObject d=documents.get(i);OriginalFiles.Entry e=entries.get(i);JSONObject a=e.item;String typ=a.optString("type"),state=a.optString("status");boolean cached=originalCached(a);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(13),dp(10),dp(13),dp(12));card.setBackground(surface(Color.WHITE,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(7),0,dp(7));content.addView(card,lp);TextView title=bold(a.optString("name"),17);title.setMaxLines(2);title.setEllipsize(TextUtils.TruncateAt.END);card.addView(title);TextView origin=text(d.optString("title"),11);origin.setMaxLines(1);origin.setEllipsize(TextUtils.TruncateAt.END);origin.setTextColor(Color.rgb(112,126,119));card.addView(origin);String label=cached?"本机已下载 · 可离线打开":state.equals("ready")?"云端就绪 · 下载后离线可用":state.equals("failed")?"获取失败 · 可重试":state.equals("unavailable")?a.optString("message"):"待获取 · Mac 在线时处理";long bytes=a.optLong("size");TextView meta=text((typ.equals("pdf")?"PDF":typ.equals("audio")?"音频":typ.equals("image")?"图片":"表格 / 文件")+(bytes>0?String.format(Locale.CHINA," · %.1f MB",bytes/1048576.0):"")+" · "+label,12);meta.setTextColor(state.equals("failed")?Color.rgb(145,91,29):cached?GREEN:Color.rgb(99,113,106));card.addView(meta);Runnable action=()->{if(state.equals("ready")&&!typ.equals("image")){JSONObject asset=new JSONObject();try{asset.put("id",a.optString("asset_id"));asset.put("name",a.optString("name"));asset.put("type",typ);}catch(Exception ignored){}openAttachment(asset);}else openOriginal(d,e.source?a.optString("id"):"");};String actionLabel=state.equals("ready")?(typ.equals("image")?"查看图片":typ.equals("pdf")?"阅读 PDF":cached?"打开原件":"下载并打开"):state.equals("failed")?"查看并重试":"查看 / 获取原件";card.addView(button(actionLabel,action));}if(entries.size()>listLimit)content.addView(button("更多文件 · 已显示 "+Math.min(listLimit,entries.size())+" / "+entries.size(),()->{int y=scroll.getScrollY();listLimit+=60;render();final int generation=navigationGeneration;scroll.post(()->{if(generation==navigationGeneration)scroll.scrollTo(0,y);});}));if(entries.isEmpty())content.addView(text("没有匹配文件；可切换文件类型、状态或清除搜索。",14));}
 private boolean originalCached(JSONObject item){String id=item.optString("asset_id");return item.optString("status").equals("ready")&&id.matches("[a-f0-9]{64}")&&new File(getFilesDir(),"asset-"+id).isFile();}
 private void openOriginal(JSONObject d,String focus){open(d,focus);}
 private void jumpToOriginal(String focus){if(attachmentBoxForArticle==null||!attachmentBoxForArticle.isAttachedToWindow())return;View target=focus.isEmpty()?attachmentBoxForArticle:attachmentBoxForArticle.findViewWithTag("attachment:"+focus);if(target==null)target=attachmentBoxForArticle;android.graphics.Rect rect=new android.graphics.Rect();target.getDrawingRect(rect);content.offsetDescendantRectToMyCoords(target,rect);scroll.scrollTo(0,Math.max(0,rect.top-dp(12)));}
 private void categoryGrid(TreeSet<String> names,String field,boolean companies){Map<String,int[]> coverage=new HashMap<>();Map<String,String> latest=new HashMap<>();for(int i=0;i<docs.length();i++){JSONObject d=docs.optJSONObject(i);JSONArray values=d.optJSONArray(field);Set<String> unique=new HashSet<>();if(values!=null)for(int j=0;j<values.length();j++){String name=values.optString(j);unique.add(companies?companyCanonical.getOrDefault(name,name):name);}boolean unread=!prefs.getBoolean("read:"+d.optString("document_id"),false);for(String name:unique){int[] count=coverage.computeIfAbsent(name,k->new int[2]);count[0]++;if(unread)count[1]++;String day=LibraryViews.day(d);if(!day.equals("日期未知")&&day.compareTo(latest.getOrDefault(name,""))>0)latest.put(name,day);}}
  ArrayList<String> ordered=new ArrayList<>(names);if(companies)ordered.sort((a,b)->{int followedOrder=Boolean.compare(companyIsFollowed(b),companyIsFollowed(a));if(followedOrder!=0)return followedOrder;int recent=latest.getOrDefault(b,"").compareTo(latest.getOrDefault(a,""));return recent!=0?recent:a.compareTo(b);});
  LinearLayout row=null;int index=0,matched=0;for(String name:ordered){if(!query.isEmpty()&&!(companies?companyQuery(name):name.toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT))))continue;matched++;if(index>=listLimit)continue;int[] count=coverage.getOrDefault(name,new int[2]);if(index%2==0){row=new LinearLayout(this);content.addView(row);}Button b=button((companies&&companyIsFollowed(name)?"★ ":"")+(companies?companyLabel(name):name)+"\n"+count[0]+" 篇 · "+count[1]+" 未读"+(companies&&!latest.getOrDefault(name,"").isEmpty()?"\n最近研究 "+latest.get(name):""),()->{if(companies)company=name;else industry=name;render();});b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);b.setBackground(surface(Color.WHITE,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);b.setMinHeight(dp(76));lp.setMargins(dp(3),dp(5),dp(3),dp(5));row.addView(b,lp);index++;}if(index%2==1)row.addView(new View(this),new LinearLayout.LayoutParams(0,dp(68),1));if(matched>index){int total=matched;content.addView(button("更多公司 · "+index+" / "+total,()->{int y=scroll.getScrollY();listLimit+=60;render();scroll.post(()->scroll.scrollTo(0,y));}));}}
 private boolean contains(JSONArray values,String value){if(values==null)return false;for(int i=0;i<values.length();i++)if(values.optString(i).equals(value))return true;return false;}
 private void open(JSONObject d){open(d,"");}
 private void open(JSONObject d,String focus){String id=d.optString("document_id");final int generation=navigationGeneration,requestGeneration=++articleRequestGeneration;status.setText("正在读取正文…");articleTasks.incrementAndGet();articleWorker.execute(()->{try{
  if(generation!=navigationGeneration||requestGeneration!=articleRequestGeneration)return;
  JSONObject full=null;
  try{File f=new File(getFilesDir(),id+".json");if(f.isFile())full=OriginalFiles.mergeCached(new JSONObject(read(f)),d);}catch(Exception ignored){}
  try{if(full==null){full=request("GET","/v1/documents/"+id,null);write(new File(getFilesDir(),id+".json"),full.toString());}JSONObject result=full;runOnUiThread(()->{if(generation==navigationGeneration&&requestGeneration==articleRequestGeneration){prefs.edit().putBoolean("read:"+id,true).apply();showArticle(result,focus);}});
  }catch(Exception e){runOnUiThread(()->{if(generation==navigationGeneration&&requestGeneration==articleRequestGeneration){status.setText("正文尚未缓存或网络不可用，联网后打开一次即可离线阅读。");Toast.makeText(this,"正文未打开，保留未读状态",Toast.LENGTH_SHORT).show();}});}
 }finally{articleTasks.decrementAndGet();}});}
 private void toggleArticleStar(String id){boolean selected=!prefs.getBoolean("star:"+id,false);prefs.edit().putBoolean("star:"+id,selected).apply();if(readerTools!=null&&readerTools.getChildAt(1) instanceof Button)((Button)readerTools.getChildAt(1)).setText(selected?"★ 已收藏":"☆ 收藏");}
 private void showArticle(JSONObject d){showArticle(d,"");}
 private void showArticle(JSONObject d,String attachmentFocus){savePosition();beginReader();articleRenderPending=true;pendingImages.clear();imagePreparations.clear();userMovedDuringRender=false;lastReadPercent=-1;currentArticle=d;headings.clear();readerMode(true);content.removeAllViews();String id=d.optString("document_id");inlineImages.clear();java.util.regex.Matcher inlineMatcher=java.util.regex.Pattern.compile("!\\[[^]]*\\]\\(asset:([a-f0-9]{64})\\)").matcher(d.optString("body"));while(inlineMatcher.find())inlineImages.add(inlineMatcher.group(1));articleImages.clear();JSONArray imageAssets=d.optJSONArray("assets");if(imageAssets!=null)for(int n=0;n<imageAssets.length();n++)if(imageAssets.optJSONObject(n).optString("type").equals("image"))articleImages.add(imageAssets.optJSONObject(n).optString("id"));LinearLayout toolbar=new LinearLayout(this);toolbar.addView(button("‹ 返回",()->returnToList()),new LinearLayout.LayoutParams(0,dp(44),1));toolbar.addView(button(prefs.getBoolean("star:"+id,false)?"★ 已收藏":"☆ 收藏",()->{toggleArticleStar(id);}),new LinearLayout.LayoutParams(0,dp(44),1));toolbar.addView(button("Aa 字号",()->new AlertDialog.Builder(this).setTitle("阅读字号").setSingleChoiceItems(new String[]{"小 · 16","标准 · 18","大 · 20"},(prefs.getInt("font_size",18)-16)/2,(dialog,which)->{prefs.edit().putInt("font_size",16+which*2).apply();dialog.dismiss();showArticle(d);}).setNegativeButton("取消",null).show()),new LinearLayout.LayoutParams(0,dp(44),1));toolbar.addView(button("目录",()->tableOfContents()),new LinearLayout.LayoutParams(0,dp(44),1));readerTools=toolbar;root.addView(toolbar,0);
  TextView eyebrow=text("归档研究  /  "+d.optString("source_name"),12);eyebrow.setTextColor(GREEN);eyebrow.setPadding(dp(4),dp(16),0,dp(4));content.addView(eyebrow);TextView articleTitle=bold(ResearchHome.displayTitle(d),25);articleTitle.setTextColor(Color.rgb(24,65,54));articleTitle.setLineSpacing(dp(4),1.05f);content.addView(articleTitle);TextView metadata=text(date(d.optString("published_at"))+"  ·  原文保留",12);metadata.setTextColor(Color.rgb(114,126,120));content.addView(metadata);HorizontalScrollView related=new HorizontalScrollView(this);LinearLayout links=new LinearLayout(this);related.addView(links);for(String field:new String[]{"industries","companies"}){JSONArray names=d.optJSONArray(field);if(names!=null)for(int n=0;n<Math.min(3,names.length());n++){String name=names.optString(n);links.addView(button(field.equals("companies")?companyLabel(name):name,()->{tab=field.equals("companies")?"公司":"行业";company=field.equals("companies")?companyCanonical.getOrDefault(name,name):"";industry=field.equals("industries")?name:"全部";feedMode="全部";sourceFilter="";dateDays=0;query="";search.setText("");render();}));}}if(links.getChildCount()>0)content.addView(related);int font=prefs.getInt("font_size",18);
  if(!d.optString("summary").isEmpty()){LinearLayout summaryBox=new LinearLayout(this);summaryBox.setOrientation(LinearLayout.VERTICAL);summaryBox.setPadding(dp(16),dp(10),dp(16),dp(14));summaryBox.setBackground(surface(Color.rgb(231,239,232),16));LinearLayout.LayoutParams summarySpace=new LinearLayout.LayoutParams(-1,-2);summarySpace.setMargins(0,dp(18),0,dp(16));content.addView(summaryBox,summarySpace);summaryBox.addView(bold("研究摘要",17));richText(summaryBox,d.optString("summary"),font-1);}renderExistingAnalysis(content,d,font);TextView bodyLabel=bold("原文阅读",14);readingProgress=bodyLabel;bodyLabel.setTextColor(GREEN);bodyLabel.setPadding(0,dp(22),0,dp(10));content.addView(bodyLabel);LinearLayout paper=new LinearLayout(this);paper.setOrientation(LinearLayout.VERTICAL);paper.setPadding(dp(14),dp(8),dp(14),dp(24));paper.setBackground(surface(Color.WHITE,16));content.addView(paper,new LinearLayout.LayoutParams(-1,-2));final int generation=navigationGeneration;float resumeAt=progress(d);new ResearchText(this,font,headings,(parent,imageId,caption)->{if(articleImages.contains(imageId)){inlineImages.add(imageId);addImage(parent,imageId,caption);}}).renderAsync(paper,d.optString("body"),()->reading&&currentArticle==d&&navigationGeneration==generation,()->{articleRenderPending=false;scheduleImages();readingProgress.setText("原文阅读 · 已排版完成");if(!userMovedDuringRender)scroll.post(()->{if(reading&&currentArticle==d&&navigationGeneration==generation){if(!attachmentFocus.isEmpty())jumpToOriginal(attachmentFocus);else scroll.scrollTo(0,Math.round(resumeAt*Math.max(0,content.getHeight()-scroll.getHeight())));}});});
  Set<String> managed=new HashSet<>();JSONArray sourceAttachments=d.optJSONArray("attachments");if(sourceAttachments!=null)for(int n=0;n<sourceAttachments.length();n++)managed.add(sourceAttachments.optJSONObject(n).optString("asset_id"));
  JSONArray assets=d.optJSONArray("assets");if(assets!=null)for(int i=0;i<assets.length();i++){JSONObject a=assets.optJSONObject(i);if(managed.contains(a.optString("id")))continue;if(a.optString("type").equals("image")){if(!inlineImages.contains(a.optString("id")))addImage(content,a.optString("id"),a.optString("name"));}else content.addView(button("打开原件 · "+a.optString("name"),()->openAttachment(a)));}
  LinearLayout attachmentBox=new LinearLayout(this);attachmentBox.setOrientation(LinearLayout.VERTICAL);content.addView(attachmentBox);attachmentBoxForArticle=attachmentBox;renderSourceAttachments(attachmentBox,d);
  String original=d.optString("source_url");if(original.startsWith("https://"))content.addView(button("打开原始来源",()->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(original)))));

  status.setText("已缓存正文，可离线阅读；手机不调用模型");
 }
 private final Set<String> imagePreparations=new HashSet<>();
 private void renderSourceAttachments(LinearLayout box,JSONObject d){box.removeAllViews();JSONArray items=d.optJSONArray("attachments");if(items==null||items.length()==0)return;box.addView(bold("原件与附件 · "+items.length(),19));box.addView(text("音频不转写，PDF 不解析。未同步原件由在线 Mac 按需获取。",12));for(int n=0;n<items.length();n++){JSONObject a=items.optJSONObject(n);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(8),dp(12),dp(12));card.setBackground(surface(Color.WHITE,12));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(7),0,dp(7));box.addView(card,lp);String typ=a.optString("type"),state=a.optString("status");card.setTag("attachment:"+a.optString("id"));card.addView(bold(a.optString("name"),15));long size=a.optLong("size");card.addView(text((typ.equals("audio")?"音频":typ.equals("pdf")?"PDF":typ.equals("image")?"图片":"表格 / 文件")+(size>0?String.format(Locale.CHINA," · %.1f MB",size/1048576.0):"")+" · "+a.optString("message"),12));if(state.equals("ready")){JSONObject asset=new JSONObject();try{asset.put("id",a.optString("asset_id"));asset.put("name",a.optString("name"));asset.put("type",typ);}catch(Exception ignored){}if(typ.equals("image")){if(!inlineImages.contains(a.optString("asset_id")))addImage(card,a.optString("asset_id"),"");}else card.addView(button(typ.equals("pdf")?"阅读 PDF 原件":"下载并打开原件",()->openAttachment(asset)));}else if(!state.equals("unavailable")){Button request=button(state.equals("failed")?"重试获取原件":"获取原件",()->{});request.setOnClickListener(v->prepareAttachment(d,a,box,request));card.addView(request);if(typ.equals("image")&&state.equals("missing")&&imagePreparations.add(a.optString("id")))box.post(()->{if(reading&&box.isAttachedToWindow())prepareAttachment(d,a,box,request);});}}}
 private void prepareAttachment(JSONObject d,JSONObject a,LinearLayout box,Button button){final int generation=navigationGeneration;button.setEnabled(false);button.setText("正在请求…");worker.execute(()->{try{request("POST","/v1/documents/"+d.optString("document_id")+"/attachments/"+a.optString("id")+"/prepare",new JSONObject());runOnUiThread(()->{if(generation!=navigationGeneration||!reading)return;button.setText("等待 Mac 获取，自动检查中…");pollAttachment(d,a,box,button,generation,0);});}catch(Exception e){runOnUiThread(()->{if(generation==navigationGeneration){button.setEnabled(true);button.setText("请求失败，点击重试");}});}});}
 private void pollAttachment(JSONObject d,JSONObject a,LinearLayout box,Button button,int generation,int attempt){foreground.postDelayed(()->{if(generation!=navigationGeneration||!reading)return;worker.execute(()->{try{JSONObject state=request("GET","/v1/documents/"+d.optString("document_id")+"/attachments/"+a.optString("id")+"/preparation",null);boolean ready=state.optString("status").equals("ready"),failed=state.optString("status").equals("failed");JSONObject latest=null;if(ready||failed)latest=request("GET","/v1/documents/"+d.optString("document_id"),null);final JSONObject updated=latest;if(ready||failed){write(new File(getFilesDir(),d.optString("document_id")+".json"),latest.toString());runOnUiThread(()->{if(generation==navigationGeneration&&reading)renderSourceAttachments(box,updated);});return;}}catch(Exception ignored){}runOnUiThread(()->{if(generation!=navigationGeneration||!reading)return;if(attempt<39)pollAttachment(d,a,box,button,generation,attempt+1);else{button.setEnabled(true);button.setText("尚未就绪，请确认 Mac 在线后重试");}});});},attempt==0?1000:4000);}
 private void openAttachment(JSONObject a){if(a.optString("type").equals("pdf")){downloadPdf(a);return;}final int generation=navigationGeneration;status.setText("正在下载原件…");worker.execute(()->{try{File file=asset(a.optString("id"));runOnUiThread(()->{if(generation!=navigationGeneration)return;status.setText("原件已缓存，可离线打开");android.net.Uri uri=new android.net.Uri.Builder().scheme("content").authority(getPackageName()+".attachments").appendPath("asset").appendPath(a.optString("id")).appendPath(a.optString("name","原件").replace('/','_')).build();Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,getContentResolver().getType(uri)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(intent,"选择应用打开原件"));}catch(ActivityNotFoundException e){Toast.makeText(this,"原件已缓存，请安装支持该格式的播放器或表格应用",Toast.LENGTH_LONG).show();}});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"原件下载失败，请重试",Toast.LENGTH_LONG).show());}});}
 private synchronized File asset(String id)throws Exception{if(!id.matches("[a-f0-9]{64}"))throw new IOException("bad asset");File file=new File(getFilesDir(),"asset-"+id);if(file.isFile())return file;
  Map<String,?> config=prefs.getAll();URL url=new URL((String)config.get("server")+"/v1/assets/"+id);HttpsURLConnection c=(HttpsURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(120000);c.setRequestProperty("Authorization","Bearer "+decrypt((String)config.get("credential")));
  File tmp=new File(file.getPath()+".tmp");try{if(c.getResponseCode()!=200)throw new IOException("asset rejected");java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");int size=0;try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(tmp)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){size+=n;if(size>100_000_000)throw new IOException("asset too large");out.write(buf,0,n);digest.update(buf,0,n);}out.getFD().sync();}StringBuilder actual=new StringBuilder();for(byte b:digest.digest())actual.append(String.format("%02x",b&255));if(!actual.toString().equals(id))throw new IOException("asset corrupt");if(!tmp.renameTo(file))throw new IOException("cache write failed");return file;}finally{c.disconnect();tmp.delete();}}
 private void launchPdf(JSONObject a){savePosition();startActivity(new Intent(this,PdfReaderActivity.class).putExtra("asset_id",a.optString("id")).putExtra("name",a.optString("name","PDF 原件.pdf")));}
 private final Set<String> pdfDownloads=new HashSet<>();
 private void downloadPdf(JSONObject a){String id=a.optString("id");if(!id.matches("[a-f0-9]{64}"))return;final int generation=navigationGeneration,requestGeneration=++articleRequestGeneration;if(new File(getFilesDir(),"asset-"+id).isFile()){launchPdf(a);return;}if(!pdfDownloads.add(id)){Toast.makeText(this,"PDF 正在下载，请稍候",Toast.LENGTH_SHORT).show();return;}Toast.makeText(this,"正在下载 PDF，完成后打开",Toast.LENGTH_SHORT).show();worker.execute(()->{try{asset(id);runOnUiThread(()->{if(generation==navigationGeneration&&requestGeneration==articleRequestGeneration)launchPdf(a);});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"PDF 下载失败，联网后重试",Toast.LENGTH_LONG).show());}finally{runOnUiThread(()->pdfDownloads.remove(id));}});}
 private boolean phoneSyncFailed=false;
 private JSONObject sourceHealth(){try{return new JSONObject(prefs.getString("source_health",""));}catch(Exception e){return null;}}
 private void saveSyncState(JSONObject state){android.content.SharedPreferences.Editor edit=prefs.edit().putString("cloud_published_at",state.optString("last_sync","")).putString("health_received_at",state.optString("health_received_at",""));JSONObject health=state.optJSONObject("source_health");if(health==null)edit.remove("source_health");else edit.putString("source_health",health.toString());edit.apply();}
 private void confirmPhoneCheck(){phoneSyncFailed=false;prefs.edit().putLong("last_phone_check",System.currentTimeMillis()).apply();}
 private void updateSyncStatus(){if(status==null)return;JSONObject health=sourceHealth();long now=System.currentTimeMillis();String received=prefs.getString("health_received_at","");status.setText(!configured()?"未连接阅读服务 · 点击设置":phoneSyncFailed?"手机同步失败 · 已缓存内容仍可阅读":ResearchHome.healthLabel(health,received,now));status.setTextColor(configured()&&!phoneSyncFailed&&ResearchHome.healthy(health,received,now)?GREEN:Color.rgb(145,91,29));}
 private String timeLabel(String value){return value==null||value.isEmpty()||value.equals("null")?"暂无记录":LibraryViews.date(value);}
 private void showSyncDetails(){if(!configured()){settings();return;}JSONObject h=sourceHealth();StringBuilder message=new StringBuilder();if(h==null)message.append("尚未收到 Mac 采集状态，无法判断源站是否更新。\n");else{message.append(h.optBoolean("poll_enabled")?"自动采集：每 "+h.optInt("poll_minutes",5)+" 分钟\n":"自动采集：已关闭\n");JSONArray sources=h.optJSONArray("sources");if(sources!=null)for(int i=0;i<sources.length();i++){JSONObject source=sources.optJSONObject(i);message.append("\n").append(source.optString("name")).append(" · ").append(ResearchHome.stateName(source.optString("status"))).append("\n最近成功采集：").append(timeLabel(source.optString("last_success_at"))).append("\n最近调度尝试：").append(timeLabel(source.optString("last_attempt_at"))).append("\n");if(source.optString("status").equals("failed")&&h.optBoolean("poll_enabled"))message.append("失败退避：至少 ").append(Math.max(15,h.optInt("poll_minutes",5))).append(" 分钟后按调度重试\n");if(source.optString("issue").equals("api_unavailable"))message.append("原因：官方接口暂不可达或返回异常\n");else if(source.optString("issue").equals("auth_required"))message.append("原因：需在 Mac 检查星球登录或访问权限\n");if(source.optInt("unavailable_count")>0)message.append("待补全主题：").append(source.optInt("unavailable_count")).append("\n");}}message.append("\nMac 最近上报：").append(timeLabel(prefs.getString("health_received_at",""))).append("\n云端资料更新：").append(timeLabel(prefs.getString("cloud_published_at","")));long checked=prefs.getLong("last_phone_check",0);java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("MM-dd HH:mm",Locale.CHINA);fmt.setTimeZone(java.util.TimeZone.getTimeZone("Asia/Shanghai"));message.append("\n手机最近成功检查：").append(checked==0?"暂无记录":fmt.format(new Date(checked)));if(phoneSyncFailed)message.append("\n当前手机同步失败，请检查网络与阅读服务连接。");message.append("\n\n源站采集失败或中断时，请在 Mac 信源设置检查并重试。手机刷新只检查云端副本。");new AlertDialog.Builder(this).setTitle("采集与同步状态").setMessage(message.toString()).setPositiveButton("检查云端",(dialog,which)->{listDirty=true;sync();}).setNeutralButton("连接设置",(dialog,which)->settings()).setNegativeButton("关闭",null).show();}
 private void renderExistingAnalysis(LinearLayout parent,JSONObject d,int font){if(!ResearchHome.analysisCurrent(d))return;JSONArray points=d.optJSONArray("key_points"),risks=d.optJSONArray("risks");if((points==null||points.length()==0)&&(risks==null||risks.length()==0))return;TextView label=text("已有 AI 整理 · 与当前原文修订一致，阅读时请核对原文",11);label.setTextColor(Color.rgb(112,126,119));parent.addView(label);analysisBlock(parent,"关键观点",points,font,false);analysisBlock(parent,"风险提示",risks,font,true);}
 private void analysisBlock(LinearLayout parent,String title,JSONArray items,int font,boolean risk){if(items==null||items.length()==0)return;LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(14),dp(8),dp(14),dp(12));panel.setBackground(surface(risk?Color.rgb(251,243,228):Color.rgb(232,241,235),14));LinearLayout.LayoutParams space=new LinearLayout.LayoutParams(-1,-2);space.setMargins(0,dp(8),0,dp(8));parent.addView(panel,space);TextView heading=bold(title,18);heading.setTextColor(risk?Color.rgb(145,91,29):GREEN);panel.addView(heading);headings.add(heading);int preview=Math.min(3,items.length());for(int i=0;i<preview;i++)richText(panel,"• "+items.optString(i),font-1);if(items.length()>preview){Button more=button("展开其余 "+(items.length()-preview)+" 条",()->{});more.setOnClickListener(v->{panel.removeView(more);for(int i=preview;i<items.length();i++)richText(panel,"• "+items.optString(i),font-1);});panel.addView(more);}}
 private void sync(){if(!configured()){settings();return;}if(syncing)return;syncing=true;status.setText("正在同步资料列表…");worker.execute(()->{try{
  JSONObject state=request("GET","/v1/status",null);saveSyncState(state);long cursor=state.optLong("cursor",-1);if(cursor>=0&&prefs.getLong("cloud_cursor",-1)==cursor){runOnUiThread(()->{confirmPhoneCheck();updateSyncStatus();if(!reading&&listDirty)refreshListInPlace();});return;}
  JSONArray all=new JSONArray();int offset=0;while(true){JSONObject page=request("GET","/v1/documents?limit=100&offset="+offset,null);JSONArray items=page.getJSONArray("documents");for(int i=0;i<items.length();i++)all.put(items.getJSONObject(i));offset+=items.length();if(!page.optBoolean("has_more"))break;if(offset>50000)throw new IOException("library too large");}
  write(new File(getFilesDir(),"catalog.json"),all.toString());JSONArray result=all;String stamp=new java.text.SimpleDateFormat("MM-dd HH:mm",Locale.CHINA).format(new Date());prefs.edit().putString("last_sync",stamp).putLong("cloud_cursor",cursor).apply();runOnUiThread(()->{docs=result;confirmPhoneCheck();updateSyncStatus();if(!reading)refreshListInPlace();else listDirty=true;});
 }catch(Exception e){runOnUiThread(()->{phoneSyncFailed=true;updateSyncStatus();});}finally{syncing=false;}});}
 private JSONObject request(String method,String path,JSONObject body)throws Exception{Map<String,?> config=prefs.getAll();String server=(String)config.get("server");URL url=new URL(server+path);if(!url.getProtocol().equals("https"))throw new IOException("HTTPS required");HttpsURLConnection conn=(HttpsURLConnection)url.openConnection();conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(15000);conn.setReadTimeout(25000);conn.setRequestMethod(method);conn.setRequestProperty("Authorization","Bearer "+decrypt((String)config.get("credential")));try{if(body!=null){conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json");try(OutputStream out=conn.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}if(conn.getResponseCode()!=200)throw new IOException("request rejected");try(InputStream in=conn.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>8_000_000)throw new IOException("response too large");out.write(buf,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{conn.disconnect();}}
 private void settings(){if(articleTasks.get()>0){Toast.makeText(this,"请等待正文读取完成后再修改连接",Toast.LENGTH_SHORT).show();return;}if(syncing){Toast.makeText(this,"请等待当前同步完成后再修改连接",Toast.LENGTH_SHORT).show();return;}LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(20),0,dp(20),0);EditText server=new EditText(this);server.setHint("https://你的私有阅读服务");server.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);server.setText(prefs.getString("server",""));box.addView(server);EditText token=new EditText(this);token.setHint("设备阅读凭据（留空保留）");token.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);box.addView(token);box.addView(text("凭据经 Android Keystore 加密保存。请勿填入 DeepSeek Key 或星球登录凭据。收藏和已读目前只存于此手机。",12));
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("连接私有阅读服务").setView(box).setNegativeButton("取消",null).setPositiveButton("保存并同步",null).create();dialog.setOnShowListener(x->dialog.getButton(-1).setOnClickListener(v->{try{String s=server.getText().toString().trim().replaceAll("/+$","");URI uri=new URI(s);if(!"https".equals(uri.getScheme())||uri.getHost()==null||uri.getUserInfo()!=null||uri.getQuery()!=null||uri.getFragment()!=null||uri.getPath().contains(".."))throw new Exception();String old=prefs.getString("server","");String t=token.getText().toString().trim();if(!t.isEmpty()&&t.length()<32)throw new Exception();if(t.isEmpty()&&(!old.equals(s)||prefs.getString("credential","").isEmpty()))throw new Exception();if(!old.equals(s)){docs=new JSONArray();for(File f:getFilesDir().listFiles())if(f.getName().endsWith(".json")||f.getName().startsWith("asset-"))f.delete();prefs.edit().clear().apply();}android.content.SharedPreferences.Editor edit=prefs.edit().putString("server",s);if(!t.isEmpty()){if(t.length()<32)throw new Exception();edit.putString("credential",encrypt(t));}edit.apply();dialog.dismiss();sync();}catch(Exception e){Toast.makeText(this,"请输入有效 HTTPS 根地址与至少32字符的阅读凭据",Toast.LENGTH_LONG).show();}}));dialog.show();}
 private javax.crypto.SecretKey secret()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("reader-token")){KeyGenerator generator=KeyGenerator.getInstance("AES","AndroidKeyStore");generator.init(new KeyGenParameterSpec.Builder("reader-token",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());return generator.generateKey();}return (javax.crypto.SecretKey)ks.getKey("reader-token",null);}
 private String encrypt(String value)throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,secret());return Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(cipher.doFinal(value.getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP);}
 private String decrypt(String value)throws Exception{String[] parts=value.split(":",2);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,secret(),new GCMParameterSpec(128,Base64.decode(parts[0],Base64.NO_WRAP)));return new String(cipher.doFinal(Base64.decode(parts[1],Base64.NO_WRAP)),StandardCharsets.UTF_8);}
 private void loadCache(){try{docs=new JSONArray(read(new File(getFilesDir(),"catalog.json")));}catch(Exception ignored){docs=new JSONArray();prefs.edit().remove("cloud_cursor").apply();}}
 private String read(File f)throws Exception{try(InputStream in=new FileInputStream(f)){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
 private synchronized void write(File f,String text)throws Exception{File tmp=new File(f.getPath()+".tmp");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(text.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(!tmp.renameTo(f))throw new IOException("cache write failed");}
 @Override public void onBackPressed(){if(reading){returnToList();return;}if(!company.isEmpty()||!industry.equals("全部")){company="";industry="全部";tab=tab.equals("行业")?"动态":tab;render();return;}super.onBackPressed();}
 @Override protected void onResume(){super.onResume();foreground.postDelayed(refresh,30000);}
 @Override protected void onPause(){savePosition();foreground.removeCallbacks(refresh);foreground.removeCallbacks(searchRefresh);super.onPause();}
 @Override protected void onDestroy(){navigationGeneration++;articleWorker.shutdownNow();worker.shutdown();imageWorker.shutdown();super.onDestroy();}
